-- Academy: rebuild Yachts Module 10 as "Your First Opportunity": 24 pages (11 with quick checks, 13 with answerable exercises
-- saved to the Broker Portfolio) + a 10-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "Your First Opportunity", "body": "<p><b>Your graduation is an action plan.</b></p><p>You have reached the final module. But this is not the end of the Academy. It is the point where learning becomes action.</p><p>You began by asking: <b>What is yachting?</b> You learned how yachts work. You explored the market. You learned why people buy and sell, how brokers discover clients, how to evaluate yachts, and how to communicate, present, negotiate and handle objections. Then you turned the question inward: <b>Could I actually build a career here?</b></p><p>Now comes the most important question of all: <b>What am I going to do next?</b></p><p>A certificate cannot create a career. A plan can. A conversation can. A relationship can. An opportunity can. Your objective in this final module is to leave the Academy with a professional launch plan that you can actually execute. Not someday. Now.</p>", "q": "What is the objective of this final module?", "opts": ["To receive a certificate that creates a career", "To leave with a professional launch plan you can actually execute", "To finish learning about yachts", "To be declared a yacht broker"], "correct": 1}, {"heading": "Chapter 1: Choose Your Direction", "body": "<p><b>You do not need to know your career in ten years</b></p><p>You do need to know what you are pursuing next.</p><p><b>Your first direction</b></p><p>&bull; <b>Primary direction:</b> the role or area you want to pursue first, such as yacht brokerage, charter brokerage, yacht management, new-build sales, yacht marketing, brokerage support, commercial or operations, or another yachting role.<br/>&bull; <b>Secondary direction:</b> a realistic alternative worth investigating.<br/>&bull; <b>Long-term possibility:</b> something you may eventually want to explore.</p><p><b>The three-column test</b></p><p>Answer these eight questions: What work do I want to do? What environment do I want to work in? What skills do I want to use? What skills do I want to develop? What am I willing to learn from the ground up? What am I not prepared to compromise on? What am I prepared to compromise on initially? What would make me change direction?</p><p><b>Don't confuse the job with the industry</b></p><p>You may love yachting but discover that brokerage isn't your preferred role. That isn't failure. The industry contains many professional paths. The objective is to find the intersection between:</p><p>&bull; what interests me<br/>&bull; what I am good at<br/>&bull; what the industry needs<br/>&bull; what kind of working life I actually want</p>", "q": "What is the objective when choosing a direction?", "opts": ["To pick the highest-paid role", "To commit to one job title forever", "To avoid any alternative routes", "To find the intersection of interest, ability, industry need and the working life you want"], "correct": 3}, {"heading": "Exercise: Choose Your Direction", "body": "<p><b>Your first direction</b></p><p>Choose a primary direction, a secondary direction and a long-term possibility. Then complete the three-column test and find your intersection.</p>", "exercise": {"intro": "Be specific. This is what you are pursuing next.", "groups": [{"title": "My directions", "section": "profile", "fields": [{"key": "d_pri", "label": "Primary direction (what I pursue first)", "type": "short", "min": 6}, {"key": "d_sec", "label": "Secondary direction (a realistic alternative)", "type": "short", "min": 6}, {"key": "d_long", "label": "Long-term possibility", "type": "short", "min": 6}]}, {"title": "The three-column test", "section": "profile", "fields": [{"key": "t_work", "label": "What work do I want to do?", "type": "long", "min": 20}, {"key": "t_env", "label": "What environment do I want to work in?", "type": "long", "min": 20}, {"key": "t_use", "label": "What skills do I want to use?", "type": "long", "min": 20}, {"key": "t_dev", "label": "What skills do I want to develop?", "type": "long", "min": 20}, {"key": "t_ground", "label": "What am I willing to learn from the ground up?", "type": "long", "min": 20}, {"key": "t_nocomp", "label": "What am I not prepared to compromise on?", "type": "long", "min": 20}, {"key": "t_comp", "label": "What am I prepared to compromise on initially?", "type": "long", "min": 20}, {"key": "t_change", "label": "What would make me change direction?", "type": "long", "min": 20}]}, {"title": "The intersection", "section": "profile", "fields": [{"key": "i_int", "label": "What interests me", "type": "long", "min": 20}, {"key": "i_good", "label": "What I am good at", "type": "long", "min": 20}, {"key": "i_need", "label": "What the industry needs", "type": "long", "min": 20}, {"key": "i_life", "label": "The working life I actually want", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 2: Build Your Target List", "body": "<p><b>Names, not vague intentions</b></p><p>You now need names. Companies. People. Locations. Opportunities.</p><p><b>Your 30-company master list</b></p><p>Start with <b>30 organisations</b>, divided into:</p><p>&bull; <b>10 priority:</b> companies you would genuinely like to approach now.<br/>&bull; <b>10 strong alternatives:</b> companies that could provide a valuable entry point.<br/>&bull; <b>10 exploration:</b> companies or adjacent businesses you want to understand better.</p><p><b>Research each company</b></p><p>Record the company, office or location, business area, yacht size and focus, relevant team, potential role, contact, why you are relevant, what you want to learn, next action, date contacted, follow-up date and outcome.</p><p><b>The target list rule</b></p><p>Do not choose companies simply because their website looks impressive. Ask: <b>\"Why would this particular organisation make sense for me?\"</b> A small specialist brokerage may provide a very different learning environment from a large international group. Neither should be assumed to be universally better. You are looking for fit.</p>", "q": "What is the target list rule?", "opts": ["Choose companies for fit with you, not because their website looks impressive", "Choose only the largest groups", "Choose only small specialist firms", "Choose whichever is advertising a role"], "correct": 0}, {"heading": "Exercise: Your 30-Company Master List", "body": "<p><b>Thirty organisations</b></p><p>Ten priority, ten strong alternatives, ten exploration. One line each: company, location, focus, potential role, why relevant, next action.</p>", "exercise": {"intro": "Fit, not fame.", "groups": [{"title": "10 priority", "section": "market", "fields": [{"key": "co_01", "label": "Company 1", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_02", "label": "Company 2", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_03", "label": "Company 3", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_04", "label": "Company 4", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_05", "label": "Company 5", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_06", "label": "Company 6", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_07", "label": "Company 7", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_08", "label": "Company 8", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_09", "label": "Company 9", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_10", "label": "Company 10", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}]}, {"title": "10 strong alternatives", "section": "market", "fields": [{"key": "co_11", "label": "Company 11", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_12", "label": "Company 12", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_13", "label": "Company 13", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_14", "label": "Company 14", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_15", "label": "Company 15", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_16", "label": "Company 16", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_17", "label": "Company 17", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_18", "label": "Company 18", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_19", "label": "Company 19", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_20", "label": "Company 20", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}]}, {"title": "10 exploration", "section": "market", "fields": [{"key": "co_21", "label": "Company 21", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_22", "label": "Company 22", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_23", "label": "Company 23", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_24", "label": "Company 24", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_25", "label": "Company 25", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_26", "label": "Company 26", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_27", "label": "Company 27", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_28", "label": "Company 28", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_29", "label": "Company 29", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}, {"key": "co_30", "label": "Company 30", "type": "long", "min": 25, "placeholder": "Company | Location | Focus | Potential role | Why relevant | Next action"}]}]}}, {"heading": "Chapter 3: Build Your Network", "body": "<p><b>Yachting is a relationship-driven industry</b></p><p>Your career will not be built entirely through job advertisements. That does not mean asking everyone for a job. It means becoming known.</p><p><b>Build your first network</b></p><p>Aim to identify <b>30 relevant people</b>: brokers, charter brokers, brokerage directors, sales managers, yacht managers, captains, senior crew, shipyard professionals, surveyors, designers, lawyers, industry specialists, recruiters and former industry professionals.</p><p><b>Your networking database</b></p><p>For each person record: name, role, company, why relevant, connection, last contact and next action. Build it as a professional relationship tool, not a collection of contacts.</p><p><b>The networking rule</b></p><p>Every conversation should have a reason. You may want insight, advice, industry knowledge, feedback, an introduction, information about a company or understanding of a role. Sometimes the best outcome of a conversation is simply: <b>\"I understand this industry better than I did before.\"</b></p>", "q": "What is the networking rule?", "opts": ["Ask every contact for a job", "Collect as many names as possible", "Every conversation should have a reason", "Only speak to senior people"], "correct": 2}, {"heading": "Exercise: Your Networking Database", "body": "<p><b>Thirty relevant people</b></p><p>One line each: name, role, company, why relevant, connection and next action.</p>", "exercise": {"intro": "A professional relationship tool, not a list of names.", "groups": [{"title": "Contacts 1 to 10", "section": "services", "fields": [{"key": "pe_01", "label": "Contact 1", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_02", "label": "Contact 2", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_03", "label": "Contact 3", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_04", "label": "Contact 4", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_05", "label": "Contact 5", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_06", "label": "Contact 6", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_07", "label": "Contact 7", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_08", "label": "Contact 8", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_09", "label": "Contact 9", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_10", "label": "Contact 10", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}]}, {"title": "Contacts 11 to 20", "section": "services", "fields": [{"key": "pe_11", "label": "Contact 11", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_12", "label": "Contact 12", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_13", "label": "Contact 13", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_14", "label": "Contact 14", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_15", "label": "Contact 15", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_16", "label": "Contact 16", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_17", "label": "Contact 17", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_18", "label": "Contact 18", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_19", "label": "Contact 19", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_20", "label": "Contact 20", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}]}, {"title": "Contacts 21 to 30", "section": "services", "fields": [{"key": "pe_21", "label": "Contact 21", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_22", "label": "Contact 22", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_23", "label": "Contact 23", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_24", "label": "Contact 24", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_25", "label": "Contact 25", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_26", "label": "Contact 26", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_27", "label": "Contact 27", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_28", "label": "Contact 28", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_29", "label": "Contact 29", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}, {"key": "pe_30", "label": "Contact 30", "type": "long", "min": 25, "placeholder": "Name | Role | Company | Why relevant | Connection | Next action"}]}]}}, {"heading": "Chapter 4: Create Your Outreach", "body": "<p><b>Start conversations</b></p><p>Your outreach should be short, specific, personal, professional and easy to respond to.</p><p><b>Your outreach structure</b></p><p>&bull; <b>1. Context:</b> why are you contacting them?<br/>&bull; <b>2. Credibility:</b> what do you bring?<br/>&bull; <b>3. Reason:</b> why this person or company?<br/>&bull; <b>4. Ask:</b> what are you requesting?<br/>&bull; <b>5. Next step:</b> what happens if they are interested?</p><p><b>Example</b></p><p><em>\"I've spent the last several years in luxury hospitality and am now transitioning toward yacht brokerage. I've been deliberately building my understanding of the market and transaction process and am particularly interested in the client and commercial side of the business. I've been following your brokerage's activity in the Mediterranean and would value 15 minutes to understand what you look for in someone entering the industry. I'm not expecting a job conversation. I'm trying to understand how I can prepare properly for the first opportunity.\"</em></p><p>The important part is not the wording. It is the intention.</p><p><b>Outreach tracker</b></p><p>For every message record the date, recipient, company, channel, reason for contact, response, follow-up date, result and next action. Never rely on memory.</p><p><b>Follow-up</b></p><p>No response does not necessarily mean no. It may mean busy, travelling, missed the message, poor timing, wrong person or insufficient context. Follow up professionally. Then move on. Don't chase indefinitely.</p>", "q": "What might no response to an outreach message mean?", "opts": ["Definitely no", "That you should message daily", "That the company is not worth contacting", "Not necessarily no: busy, poor timing, wrong person or insufficient context"], "correct": 3}, {"heading": "Exercise: Your Outreach", "body": "<p><b>Write your outreach</b></p><p>Write one message using the five-part structure, set up your tracker and write a professional follow-up.</p>", "exercise": {"intro": "Short, specific, personal, easy to answer.", "groups": [{"title": "My outreach message, part by part", "section": "services", "fields": [{"key": "o_ctx", "label": "1. Context: why are you contacting them?", "type": "long", "min": 25}, {"key": "o_cred", "label": "2. Credibility: what do you bring?", "type": "long", "min": 25}, {"key": "o_reason", "label": "3. Reason: why this person or company?", "type": "long", "min": 25}, {"key": "o_ask", "label": "4. Ask: what are you requesting?", "type": "long", "min": 25}, {"key": "o_next", "label": "5. Next step: what happens if they are interested?", "type": "long", "min": 25}, {"key": "o_full", "label": "The complete message (about 100 to 150 words)", "type": "long", "min": 350}]}, {"title": "Tracker and follow-up", "section": "services", "fields": [{"key": "o_track", "label": "How I will track every message (fields, tool, weekly review)", "type": "long", "min": 40}, {"key": "o_follow", "label": "My follow-up message and when I will send it", "type": "long", "min": 120}, {"key": "o_stop", "label": "When I stop following up, and what I do then", "type": "long", "min": 40}]}]}}, {"heading": "Chapter 5: The Final Broker Challenge", "body": "<p><b>Everything you have learned comes together</b></p><p>This is the final practical assessment of the Academy.</p><p><b>The scenario</b></p><p>You are representing a fictional client couple, <b>David and Elena</b>, considering their first yacht.</p><p>&bull; approximately 8 million euros budget<br/>&bull; Mediterranean cruising, approximately 4 to 6 weeks per year<br/>&bull; two children, with family and friends onboard<br/>&bull; strong preference for outdoor living<br/>&bull; they value privacy<br/>&bull; limited yacht ownership experience<br/>&bull; they do not want ownership to become unnecessarily complicated<br/>&bull; open to brokerage rather than new build<br/>&bull; uncertain about exactly what they need</p><p>They tell you: <em>\"We know we want something special, but we don't really know what that means yet.\"</em></p><p><b>Three yachts</b></p><p>&bull; <b>Yacht A:</b> 35.2m, 2016, 8.80m euros asking, 5 cabins, 10 guests, 245 GT, 12 kn cruise, 26 kn maximum, strong private-use history highlighted, large volume, currently above the stated budget.<br/>&bull; <b>Yacht B:</b> 34.1m, 2016, 7.29m euros asking, 5 cabins, 10 guests, 266 GT, 10 kn cruise, 18 kn maximum, private-use history, recent refit and upgrades, lower asking price.<br/>&bull; <b>Yacht C:</b> 34.64m, 2017, 7.95m euros asking, 5 cabins, 10 guests, 18 kn cruise, 25.5 kn maximum, large aft beach club, sky deck, lateral tender garage, approximately 1,620 engine hours listed.</p><p><b>Important</b></p><p>These figures are provided for the exercise. Do not invent ownership details, maintenance history, VAT status, crew arrangements, operating costs, technical condition, refit scope, survey results or financial information. If you don't know, <b>say that you don't know.</b> A broker's credibility is damaged much faster by invented certainty than by acknowledged uncertainty.</p><p><b>Your task: 90 minutes</b></p><p>Your job is not simply to select a yacht. It is to demonstrate the complete broker process across ten parts: discovery, market assessment, shortlist, investigation, recommendation, client pushback, a changed brief, the viewing, the negotiation and the follow-up. The next pages take you through each one.</p>", "q": "What should you do if you don't know a fact about a yacht in the challenge?", "opts": ["Estimate it confidently", "Say that you don't know", "Invent a plausible detail", "Ignore the gap"], "correct": 1}, {"heading": "Challenge Parts 1 and 2: Discovery and Market Assessment", "body": "<p><b>Part 1: Client discovery</b></p><p>Identify <b>10 things you still need to discover</b>, across lifestyle, practical requirements, financial, ownership, emotional or motivational, and decision-making. Then choose the <b>three questions you would ask first</b> and explain why.</p><p><b>Part 2: Market assessment</b></p><p>Evaluate all three yachts. For each: client fit, strength, concern, unknown and next step.</p>", "exercise": {"intro": "Separate what you know from what you don't.", "groups": [{"title": "Part 1: Ten things I still need to discover", "section": "services", "fields": [{"key": "p1_1", "label": "1. Lifestyle", "type": "long", "min": 20}, {"key": "p1_2", "label": "2. Lifestyle", "type": "long", "min": 20}, {"key": "p1_3", "label": "3. Practical requirements", "type": "long", "min": 20}, {"key": "p1_4", "label": "4. Practical requirements", "type": "long", "min": 20}, {"key": "p1_5", "label": "5. Financial", "type": "long", "min": 20}, {"key": "p1_6", "label": "6. Ownership", "type": "long", "min": 20}, {"key": "p1_7", "label": "7. Ownership", "type": "long", "min": 20}, {"key": "p1_8", "label": "8. Emotional or motivational", "type": "long", "min": 20}, {"key": "p1_9", "label": "9. Decision-making", "type": "long", "min": 20}, {"key": "p1_10", "label": "10. Decision-making", "type": "long", "min": 20}, {"key": "p1_first", "label": "The three questions I would ask first, and why", "type": "long", "min": 120}]}, {"title": "Yacht A", "section": "yachts", "fields": [{"key": "ya_fit", "label": "Client fit", "type": "long", "min": 25}, {"key": "ya_str", "label": "Strength", "type": "long", "min": 25}, {"key": "ya_con", "label": "Concern", "type": "long", "min": 25}, {"key": "ya_unk", "label": "Unknown (what must be verified)", "type": "long", "min": 25}, {"key": "ya_next", "label": "Next step", "type": "long", "min": 25}]}, {"title": "Yacht B", "section": "yachts", "fields": [{"key": "yb_fit", "label": "Client fit", "type": "long", "min": 25}, {"key": "yb_str", "label": "Strength", "type": "long", "min": 25}, {"key": "yb_con", "label": "Concern", "type": "long", "min": 25}, {"key": "yb_unk", "label": "Unknown (what must be verified)", "type": "long", "min": 25}, {"key": "yb_next", "label": "Next step", "type": "long", "min": 25}]}, {"title": "Yacht C", "section": "yachts", "fields": [{"key": "yc_fit", "label": "Client fit", "type": "long", "min": 25}, {"key": "yc_str", "label": "Strength", "type": "long", "min": 25}, {"key": "yc_con", "label": "Concern", "type": "long", "min": 25}, {"key": "yc_unk", "label": "Unknown (what must be verified)", "type": "long", "min": 25}, {"key": "yc_next", "label": "Next step", "type": "long", "min": 25}]}]}}, {"heading": "Challenge Parts 3 and 4: Shortlist and Investigation", "body": "<p><b>Part 3: Shortlist</b></p><p>Create your current shortlist: one, two or all three yachts. There is no predetermined correct shortlist. Your reasoning is what matters. Why do these yachts deserve further attention at this stage?</p><p><b>Part 4: Investigation</b></p><p>Write <b>12 questions</b> that could materially change your assessment: 4 for the listing broker, 4 for technical specialists and 4 for David and Elena.</p>", "exercise": {"intro": "Specific, evidence-seeking and decision-relevant.", "groups": [{"title": "Part 3: Shortlist", "section": "yachts", "fields": [{"key": "sl_list", "label": "My current shortlist", "type": "short", "min": 4}, {"key": "sl_why", "label": "Why these yachts deserve further attention at this stage", "type": "long", "min": 120}]}, {"title": "Part 4: Four questions for the listing broker", "section": "yachts", "fields": [{"key": "q_lb1", "label": "Listing broker question 1", "type": "long", "min": 20}, {"key": "q_lb2", "label": "Listing broker question 2", "type": "long", "min": 20}, {"key": "q_lb3", "label": "Listing broker question 3", "type": "long", "min": 20}, {"key": "q_lb4", "label": "Listing broker question 4", "type": "long", "min": 20}]}, {"title": "Four questions for technical specialists", "section": "yachts", "fields": [{"key": "q_ts1", "label": "Technical question 1", "type": "long", "min": 20}, {"key": "q_ts2", "label": "Technical question 2", "type": "long", "min": 20}, {"key": "q_ts3", "label": "Technical question 3", "type": "long", "min": 20}, {"key": "q_ts4", "label": "Technical question 4", "type": "long", "min": 20}]}, {"title": "Four questions for David and Elena", "section": "yachts", "fields": [{"key": "q_cl1", "label": "Client question 1", "type": "long", "min": 20}, {"key": "q_cl2", "label": "Client question 2", "type": "long", "min": 20}, {"key": "q_cl3", "label": "Client question 3", "type": "long", "min": 20}, {"key": "q_cl4", "label": "Client question 4", "type": "long", "min": 20}]}]}}, {"heading": "Challenge Parts 5 to 7: Recommendation, Pushback and Changed Brief", "body": "<p><b>Part 5: Client recommendation</b></p><p>About <b>300 words</b>: what you understand about the clients, which opportunities deserve attention, why, the major trade-offs, what remains unknown and what you recommend doing next. Do not pretend certainty where the evidence does not support it.</p><p><b>Part 6: Client pushback</b></p><p>David says: <em>\"Why are you making this so complicated? Can't you just tell me which yacht is best?\"</em> Write your response.</p><p><b>Part 7: The brief changes</b></p><p>Elena says: <em>\"Actually, 7.5 million euros is our absolute maximum. We don't want to go above it.\"</em> In <b>150 to 200 words</b>: what changes, what remains interesting, what should be removed, what you need to confirm and what you would do next.</p>", "exercise": {"intro": "Structured, honest and client-centred.", "groups": [{"title": "Part 5: Recommendation", "section": "sales", "fields": [{"key": "r5", "label": "Your recommendation (about 300 words)", "type": "long", "min": 850}]}, {"title": "Part 6: Client pushback", "section": "sales", "fields": [{"key": "r6", "label": "Your response to David", "type": "long", "min": 250}]}, {"title": "Part 7: The brief changes", "section": "sales", "fields": [{"key": "r7", "label": "Your reassessment (150 to 200 words)", "type": "long", "min": 450}]}]}}, {"heading": "Challenge Part 8: The Viewing", "body": "<p><b>Part 8: The viewing</b></p><p>Choose the yacht you would view first and prepare a <b>15-minute viewing plan</b>.</p>", "exercise": {"intro": "Use the viewing to observe, test and discover.", "groups": [{"title": "My viewing plan", "section": "sales", "fields": [{"key": "v_yacht", "label": "The yacht I would view first, and why", "type": "long", "min": 40}, {"key": "v_before", "label": "Before arrival: what do I need to know?", "type": "long", "min": 40}, {"key": "v_open", "label": "Opening: what do I tell the clients?", "type": "long", "min": 40}, {"key": "v_first", "label": "First impression: what do I want them to experience?", "type": "long", "min": 40}, {"key": "v_key", "label": "Key areas: what will I show and why?", "type": "long", "min": 40}, {"key": "v_q", "label": "Questions: what will I ask during the viewing?", "type": "long", "min": 40}, {"key": "v_obs", "label": "Observation: what client reactions will I watch for?", "type": "long", "min": 40}, {"key": "v_con", "label": "Concern: what potential weakness will I investigate?", "type": "long", "min": 40}, {"key": "v_close", "label": "Closing: what will I ask the clients afterwards?", "type": "long", "min": 40}, {"key": "v_next", "label": "Next step: what should happen afterwards?", "type": "long", "min": 40}]}]}}, {"heading": "Challenge Parts 9 and 10: Negotiation and Follow-Up", "body": "<p><b>Part 9: The negotiation</b></p><p>The clients want to offer <b>7.1 million euros</b> against an asking price of <b>7.95 million euros.</b> Do not assume the negotiation will succeed. Write: A, the questions you would ask your client before communicating the offer; B, the information you want from the seller or listing broker; C, how you would present the offer professionally; D, what you would do if the seller counters at 7.7 million euros.</p><p><b>Part 10: Professional follow-up</b></p><p>Write the email you would send David and Elena after the viewing: what you observed, what they appeared to like, what concerns emerged, what remains unknown, your current assessment and the recommended next step. Professional and concise.</p>", "exercise": {"intro": "Separate client instructions, evidence, strategy and uncertainty.", "groups": [{"title": "Part 9: The negotiation", "section": "sales", "fields": [{"key": "n_a", "label": "A. Questions for my client before communicating the offer", "type": "long", "min": 80}, {"key": "n_b", "label": "B. Information I would want from the seller or listing broker", "type": "long", "min": 80}, {"key": "n_c", "label": "C. How I would present the offer professionally", "type": "long", "min": 80}, {"key": "n_d", "label": "D. What I would do if the seller counters at 7.7 million euros", "type": "long", "min": 80}]}, {"title": "Part 10: Follow-up email", "section": "sales", "fields": [{"key": "fu_email", "label": "Your email to David and Elena", "type": "long", "min": 300}]}]}}, {"heading": "Challenge Rubric and Model Thinking", "body": "<p><b>The process of professional thinking</b></p><p>The final assessment is not about choosing the \"correct\" yacht. There is deliberately no single correct answer. It measures your <b>process of professional thinking</b>, from developing to competent to strong:</p><p>&bull; <b>Client discovery:</b> from relying on assumptions, to identifying important missing information, to prioritising the questions that could materially change the recommendation.<br/>&bull; <b>Market analysis:</b> from repeating specifications, to identifying strengths and concerns, to interpreting information in the context of the client.<br/>&bull; <b>Shortlisting:</b> from choosing on price or appearance, to reasonable reasoning, to disciplined comparison that acknowledges uncertainty.<br/>&bull; <b>Investigation:</b> from generic questions, to relevant ones, to specific, evidence-seeking, decision-relevant ones.<br/>&bull; <b>Recommendation:</b> from describing yachts, to a reasoned recommendation, to clearly connecting client needs, evidence, trade-offs and next steps.<br/>&bull; <b>Viewing:</b> from giving a tour, to connecting areas to client needs, to using the viewing to observe, test and discover.<br/>&bull; <b>Negotiation:</b> from focusing mainly on price, to understanding positions and limits, to separating client instructions, evidence, strategy and uncertainty.<br/>&bull; <b>Communication:</b> from long or vague, to clear and professional, to concise, precise, client-focused and commercially appropriate.<br/>&bull; <b>Integrity:</b> from overstating unknowns, to identifying some uncertainty, to consistently separating fact, assumption and verification.<br/>&bull; <b>Broker judgment and next-step thinking:</b> from reacting to information and ending without direction, to structured, client-centred judgment where every stage leads to the next professional action.</p><p><b>What counts as strong?</b></p><p>A strong broker does not necessarily know everything. They know what they know, what they don't know, what matters, what needs verifying, what question to ask next and what the client needs to decide. That is judgment.</p><p><b>Model thinking</b></p><p><em>\"At this stage, I would keep B and C under active consideration rather than making a final recommendation. B appears attractive because it sits comfortably within the current budget and offers the required cabin capacity and volume. C appears particularly relevant to the clients' emphasis on outdoor living, but I would want to understand more about the ownership, technical and operational history before placing too much weight on the listed features. A is interesting but currently sits above the stated budget, so I would not treat it as a realistic option until I understand whether the budget is genuinely flexible. My next step would be to clarify the clients' priorities around outdoor space, speed, ownership simplicity and budget, then obtain the missing information before arranging viewings.\"</em></p><p>Notice the language: <b>at this stage, appears, I would want to understand, I would not assume, my next step.</b> That is professional judgment without pretending certainty.</p>", "q": "What does the model recommendation do well?", "opts": ["It names a single winner immediately", "It ignores the budget", "It uses cautious, evidence-based language and ends with a clear next step", "It avoids mentioning unknowns"], "correct": 2}, {"heading": "Chapter 6: Your 30 / 60 / 90-Day Plan", "body": "<p><b>The Academy ends with action</b></p><p>Your plan should begin the day after graduation.</p><p><b>Days 1 to 30: build your foundation</b></p><p>&bull; <b>Knowledge:</b> keep learning yacht types, major builders, major brokerage markets, terminology, the transaction process and current market activity.<br/>&bull; <b>Positioning:</b> complete your CV, professional profile, introduction, professional networking profile and portfolio.<br/>&bull; <b>Research:</b> complete 30 target companies, 30 industry contacts and 10 priority contacts.<br/>&bull; <b>Activity:</b> 5 targeted outreach messages per week, 2 industry conversations per month and 1 relevant industry event, visit or professional interaction where practical.</p><p><b>Days 31 to 60: enter the conversation</b></p><p>Focus on networking, company conversations, applications, interviews, market observation, yacht viewings where accessible and industry events. Track who you contacted, what you learned, what changed, who introduced you to whom and what opportunities emerged.</p><p><b>Days 61 to 90: create the opportunity</b></p><p>Actively pursue interviews, internships, junior roles, brokerage opportunities, support roles, charter opportunities, management opportunities and relevant introductions. If the original route is not producing results, don't simply repeat the same action. Review: is the role wrong? the target market? the location? Is the positioning unclear, the outreach too generic, or a knowledge gap holding you back? Is another yachting role a better entry point? <b>Change the strategy based on evidence.</b></p><p><b>Your weekly career scorecard</b></p><p>Every Friday record targets against actuals: new industry contacts (5), personalised outreach (5), follow-ups (5), industry conversations (1), companies researched (2), yachts studied (3), hours of structured learning (3) and applications or opportunities pursued (2). The numbers are not the objective. <b>Consistent professional activity is.</b> Adjust the targets to your circumstances.</p>", "q": "What should you do if your original route is not producing results?", "opts": ["Review what is not working and change the strategy based on evidence", "Repeat exactly the same actions", "Stop networking", "Wait for a job advertisement"], "correct": 0}, {"heading": "Exercise: Your 30 / 60 / 90-Day Plan", "body": "<p><b>Your plan</b></p><p>Begin the day after graduation. Make every action measurable.</p>", "exercise": {"intro": "Measurable, sequenced and honest about your circumstances.", "groups": [{"title": "My three phases", "section": "profile", "fields": [{"key": "p30", "label": "Days 1 to 30: build my foundation (knowledge, positioning, research, activity)", "type": "long", "min": 100}, {"key": "p60", "label": "Days 31 to 60: enter the conversation", "type": "long", "min": 100}, {"key": "p90", "label": "Days 61 to 90: create the opportunity", "type": "long", "min": 100}]}, {"title": "Change the strategy", "section": "profile", "fields": [{"key": "p_rev", "label": "How I will review results at day 60 and 90, and what would make me change route", "type": "long", "min": 80}]}, {"title": "My weekly scorecard targets", "section": "profile", "fields": [{"key": "sc_contacts", "label": "New industry contacts per week", "type": "short", "min": 1}, {"key": "sc_out", "label": "Personalised outreach per week", "type": "short", "min": 1}, {"key": "sc_follow", "label": "Follow-ups per week", "type": "short", "min": 1}, {"key": "sc_conv", "label": "Industry conversations per week", "type": "short", "min": 1}, {"key": "sc_comp", "label": "Companies researched per week", "type": "short", "min": 1}, {"key": "sc_yachts", "label": "Yachts studied per week", "type": "short", "min": 1}, {"key": "sc_learn", "label": "Hours of structured learning per week", "type": "short", "min": 1}, {"key": "sc_apps", "label": "Applications or opportunities pursued per week", "type": "short", "min": 1}, {"key": "sc_adjust", "label": "How I have adjusted these targets to my circumstances", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 7: Your First 10 Opportunities", "body": "<p><b>Find ten opportunities to create movement</b></p><p>Not \"find a job.\" An opportunity could be a job application, an introduction, an informational conversation, an internship, a junior role, a brokerage assistant position, a charter opportunity, a company visit, an industry event, a meeting with a broker, a project, a short-term placement or another legitimate entry route.</p><p><b>Your first ten</b></p><p>For each: organisation or person, the opportunity, why it is relevant, contact, date and next action.</p><p><b>The first-10 rule</b></p><p>Do not wait until the list is perfect. Your first ten opportunities are designed to create information. Some may lead nowhere. Some may lead to a conversation. Some may lead to an introduction. One may lead somewhere unexpected. The objective is movement.</p><p><b>Your career launch statement</b></p><p>Write about <b>200 words</b> answering: where am I going, why am I going there, what do I bring, what do I still need to learn, who am I going to speak to, and what will I do in the next seven days?</p>", "q": "What is the objective of the first-10 rule?", "opts": ["A guaranteed job offer", "Movement: creating information and momentum rather than waiting for a perfect list", "A perfect list before you start", "Ten job applications only"], "correct": 1}, {"heading": "Exercise: Your First 10 and Launch Statement", "body": "<p><b>Create movement</b></p><p>List your first ten opportunities, write your launch statement and commit to your next seven days.</p>", "exercise": {"intro": "Do not wait until the list is perfect.", "groups": [{"title": "My first 10 opportunities", "section": "services", "fields": [{"key": "op_01", "label": "Opportunity 1", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_02", "label": "Opportunity 2", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_03", "label": "Opportunity 3", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_04", "label": "Opportunity 4", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_05", "label": "Opportunity 5", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_06", "label": "Opportunity 6", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_07", "label": "Opportunity 7", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_08", "label": "Opportunity 8", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_09", "label": "Opportunity 9", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}, {"key": "op_10", "label": "Opportunity 10", "type": "long", "min": 30, "placeholder": "Organisation / person | Opportunity | Why relevant | Contact | Date | Next action"}]}, {"title": "My career launch statement", "section": "profile", "fields": [{"key": "ls_go", "label": "Where am I going, and why?", "type": "long", "min": 60}, {"key": "ls_bring", "label": "What do I bring, and what do I still need to learn?", "type": "long", "min": 60}, {"key": "ls_who", "label": "Who am I going to speak to?", "type": "long", "min": 40}, {"key": "ls_full", "label": "My career launch statement (about 200 words)", "type": "long", "min": 550}]}, {"title": "My next seven days", "section": "profile", "fields": [{"key": "d1", "label": "Day 1: finalise my professional profile", "type": "long", "min": 15}, {"key": "d2", "label": "Day 2: complete my first-10 opportunity list", "type": "long", "min": 15}, {"key": "d3", "label": "Day 3: research my five highest-priority organisations", "type": "long", "min": 15}, {"key": "d4", "label": "Day 4: identify the relevant people within them", "type": "long", "min": 15}, {"key": "d5", "label": "Day 5: send my first personalised outreach", "type": "long", "min": 15}, {"key": "d6", "label": "Day 6: follow up on existing conversations", "type": "long", "min": 15}, {"key": "d7", "label": "Day 7: review what happened and decide my next seven actions", "type": "long", "min": 15}]}]}}, {"heading": "Graduation Checklist and Your Broker Portfolio", "body": "<p><b>Before you consider the Academy complete</b></p><p>Confirm that you have:</p><p>&bull; <b>Knowledge:</b> completed the Academy modules, built your yacht terminology, compared yachts, analysed a market, built a client brief, practised a broker recommendation and completed communication exercises.<br/>&bull; <b>Professional skills:</b> conducted client discovery, practised a yacht presentation, completed a viewing exercise, practised objection handling and negotiation, and written a professional follow-up.<br/>&bull; <b>Career:</b> identified your preferred direction and alternative routes, mapped transferable skills, created your introduction, researched target companies, built your networking database, prepared outreach and interview answers.<br/>&bull; <b>Launch:</b> created your 30 / 60 / 90-day plan, built your first-10 list and weekly scorecard, completed the Final Broker Challenge, created your Broker Portfolio and defined your next seven actions.</p><p><b>Your Broker Portfolio</b></p><p>At graduation you should have accumulated a body of work: My Yacht World Map, My Yacht Comparison, My First Market Analysis, My Client Brief, My First Broker Recommendation, My Broker Communication Playbook, My Transferable Skills Map, My Professional Profile, My Target Company List, My Networking Database, My Outreach Plan, My Career Entry Plan, My Final Broker Challenge, My 30 / 60 / 90-Day Plan and My First 10 Opportunities.</p><p>This is more valuable than a certificate alone. It demonstrates what you can think about, what you can produce and how seriously you have approached the career change.</p>", "q": "Why is the Broker Portfolio more valuable than a certificate alone?", "opts": ["It replaces the need to network", "It guarantees an interview", "It is required by law", "It demonstrates what you can think about, produce and how seriously you approached the change"], "correct": 3}, {"heading": "Exercise: Final Knowledge Check", "body": "<p><b>Answer without looking back</b></p><p>Answer these ten questions in your own words, without looking back through the Academy. <b>If you cannot answer the final question clearly, you are not finished.</b></p>", "exercise": {"intro": "Your own words. Short and clear.", "groups": [{"title": "Final knowledge check", "section": "profile", "fields": [{"key": "kc_1", "label": "1. What is a yacht broker actually selling?", "type": "long", "min": 30}, {"key": "kc_2", "label": "2. Why is understanding the client more important than memorising specifications?", "type": "long", "min": 30}, {"key": "kc_3", "label": "3. What makes a yacht valuable?", "type": "long", "min": 30}, {"key": "kc_4", "label": "4. What is the difference between a feature and a client benefit?", "type": "long", "min": 30}, {"key": "kc_5", "label": "5. Why should a broker acknowledge uncertainty?", "type": "long", "min": 30}, {"key": "kc_6", "label": "6. What makes a good yacht recommendation?", "type": "long", "min": 30}, {"key": "kc_7", "label": "7. What should happen before an offer is made?", "type": "long", "min": 30}, {"key": "kc_8", "label": "8. What is the broker's responsibility during negotiation?", "type": "long", "min": 30}, {"key": "kc_9", "label": "9. What transferable skills could you bring into yachting?", "type": "long", "min": 30}, {"key": "kc_10", "label": "10. What is your next professional action?", "type": "long", "min": 30}]}]}}, {"heading": "Exercise: Final Reflection", "body": "<p><b>Return to the question from Module 1</b></p><p><em>\"Could I genuinely see myself building a career here?\"</em> Now answer it again, but not from imagination. Answer from experience. You have studied yachts, examined the market, explored the people, worked through client scenarios, practised recommendations, viewings, objections and negotiation, built a career strategy and completed a broker challenge.</p>", "exercise": {"intro": "Honest, based on experience.", "groups": [{"title": "My final reflection", "section": "profile", "fields": [{"key": "fr_ans", "label": "Could I genuinely see myself building a career here? (answer from experience)", "type": "long", "min": 80}, {"key": "fr_1", "label": "What energised me?", "type": "long", "min": 25}, {"key": "fr_2", "label": "What challenged me?", "type": "long", "min": 25}, {"key": "fr_3", "label": "What did I want to learn more about?", "type": "long", "min": 25}, {"key": "fr_4", "label": "What did I find surprisingly difficult?", "type": "long", "min": 25}, {"key": "fr_5", "label": "What did I genuinely enjoy?", "type": "long", "min": 25}, {"key": "fr_6", "label": "Where could I contribute?", "type": "long", "min": 25}, {"key": "fr_7", "label": "What do I need to improve?", "type": "long", "min": 25}, {"key": "fr_8", "label": "What will I do next?", "type": "long", "min": 25}]}]}}, {"heading": "Graduation", "body": "<p><b>Your Academy ends here</b></p><p>You do not graduate because you know everything about yachts. You don't. No developing broker does. You graduate because you have learned how to approach the business professionally. You know how to <b>ask, listen, investigate, compare, question, present, advise, negotiate, follow up, build relationships and keep learning.</b> And, most importantly: <b>you know what to do next.</b></p><p><b>Your next seven days</b></p><p>Do not finish this Academy by closing the PDF. Within seven days: finalise your profile, complete your first-10 list, research your five highest-priority organisations, identify the relevant people within them, send your first personalised outreach, follow up on existing conversations, then review what happened and decide your next seven actions. Then repeat.</p><p><b>One final principle</b></p><p>The yacht industry does not need another person who simply wants to work around yachts. It needs professionals who can create value. Learn the asset. Understand the client. Respect the process. Protect the relationship. Know what you don't know. And keep moving.</p><p><b>Your Academy ends here. Your career starts with what you do next.</b></p>", "q": "According to the final principle, what does the industry need?", "opts": ["Professionals who can create value", "More people who simply want to be around yachts", "Only experienced brokers", "Fewer new entrants"], "correct": 0}]$json$;
  v_final jsonb := $json$[{"q": "What is a yacht broker actually selling?", "opts": ["Only the yacht's specifications", "The lowest possible price", "Professional judgment and trusted advice that helps clients make good decisions, not just a boat", "Access to a marina"], "correct": 2}, {"q": "Why is understanding the client more important than memorising specifications?", "opts": ["Specifications only matter in relation to what the client needs, wants and will actually do", "Specifications are never useful", "Clients never ask about specifications", "It makes viewings shorter"], "correct": 0}, {"q": "What is the difference between a feature and a client benefit?", "opts": ["They are the same thing", "A benefit is a technical specification", "A feature is what the client feels", "A feature is what the yacht has; a benefit is what that feature means for this client"], "correct": 3}, {"q": "Why should a broker acknowledge uncertainty?", "opts": ["It shows weakness and loses deals", "Invented certainty damages credibility far faster than acknowledged uncertainty", "It lets the broker avoid research", "Clients prefer vague answers"], "correct": 1}, {"q": "What makes a good yacht recommendation?", "opts": ["Naming the most expensive yacht", "Listing every specification", "It connects client needs, evidence, trade-offs and unknowns to a clear next step", "Choosing whichever yacht is cheapest"], "correct": 2}, {"q": "What should happen before an offer is made?", "opts": ["Send the offer immediately", "Guess the seller's lowest price", "Avoid asking the client questions", "Clarify the client's instructions and limits and gather the information you need from the seller side"], "correct": 3}, {"q": "What is the broker's responsibility during negotiation?", "opts": ["To separate client instructions, evidence and strategy, and not to assume the negotiation will succeed", "To win at any cost", "To reveal the client's maximum budget", "To hide unknowns from the client"], "correct": 0}, {"q": "If a client's budget cap drops below a yacht's asking price, what should a broker do?", "opts": ["Ignore the new budget", "Reassess honestly, remove what no longer fits, confirm what is unknown and propose a next step", "Push the client to stretch", "Hide the change from the seller"], "correct": 1}, {"q": "What is the purpose of your first ten opportunities?", "opts": ["To secure a job offer immediately", "To avoid networking", "To replace the 30/60/90-day plan", "To create movement and information rather than wait for a perfect list"], "correct": 3}, {"q": "What should you do if your outreach is not producing results after 60 to 90 days?", "opts": ["Repeat exactly the same outreach", "Stop and give up", "Review the role, market, location, positioning, outreach and knowledge gaps, and change the strategy based on evidence", "Send more generic messages"], "correct": 2}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 10;
  if v_module is null then
    raise exception 'Yachts module 10 not found';
  end if;

  update public.academy_modules
     set title = 'Your First Opportunity', description = 'Your graduation is an action plan.'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
